import { useState } from 'react';
import {
  Button,
  Dialog,
  DialogHeader,
  DialogTitle,
  DialogBody,
  DialogFooter,
  Text,
} from '@jinx-ui/react';

interface DeleteProjectButtonProps {
  onConfirm: () => void;
}

export default function DeleteProjectButton({ onConfirm }: DeleteProjectButtonProps) {
  const [isOpen, setIsOpen] = useState(false);

  const handleConfirm = () => {
    onConfirm();
    setIsOpen(false);
  };

  return (
    <>
      <Button variant="danger" onClick={() => setIsOpen(true)}>
        Удалить проект
      </Button>

      <Dialog open={isOpen} onOpenChange={setIsOpen}>
        <DialogHeader>
          <DialogTitle>Удалить проект?</DialogTitle>
        </DialogHeader>
        <DialogBody>
          <Text style={{ color: 'var(--jx-color-text-secondary)' }}>
            Это действие необратимо. Все данные проекта будут удалены без возможности восстановления.
          </Text>
        </DialogBody>
        <DialogFooter>
          <Button variant="secondary" onClick={() => setIsOpen(false)}>
            Отмена
          </Button>
          <Button variant="danger" onClick={handleConfirm}>
            Удалить
          </Button>
        </DialogFooter>
      </Dialog>
    </>
  );
}

